\label{ass:regularity}
\begin{enumerate}
\par\hangindent 40\p@[(i)] The stationary mean AoI $\mathbb{E}_\lambda[A]$ is well defined, finite, and continuously differentiable on $\lambda \in \mathcal{L} = [\lambda_{\min}, \lambda_{\max}]$.

\par\hangindent 40\p@[(ii)] The gradient of $\mathbb{E}_\lambda[A]$ admits the representation \eqref{eq:g(lambda,theta)-def} for a known function $g$ and a parameter vector $\bm{\theta}_{\lambda} \in \Theta$, where $\Theta \subseteq \mathbb{R}^d$ denotes the parameter space.

\par\hangindent 40\p@[(iii)] There exists a unique $\lambda_* \in \mathcal{L}$ such that
\[
g(\lambda_*;\bm{\theta}_{\lambda_*}) + \kappa'(\lambda_*) = 0.
\]

\par\hangindent 40\p@[(iv)] There exists a constant $C_1 > 0$ such that, for all $\bm{\theta}, \bm{\theta}' \in \Theta$ and all $\lambda\in{\mathcal L}$,
\begin{equation} \label{eq:Lips}
|g(\lambda;\bm{\theta}) - g(\lambda;\bm{\theta}')| \le C_1 \|\bm{\theta} - \bm{\theta}'\|.
\end{equation}
\par\hangindent 40\p@[(v)] There exists a constant $C_2 > 0$ such that,  for all $\lambda\in{\mathcal L}$,

\begin{equation}\label{eq:theta_mixing}
\mathbb{E}_{\lambda^{\langle k\rangle}}\!\left[ \|\bm{\theta}_{\lambda^{\langle k\rangle}} - \hat{\bm{\theta}}^{\langle k\rangle}\|^2\, \Big|\, \,
\mathcal{F}^{\langle k-1\rangle}, \lambda^{\langle k\rangle} \right]
\le \frac{C_2}{n^{\langle k\rangle}}, \qquad k=1,2,\ldots,
\end{equation}
where $\mathcal{F}^{\langle k-1\rangle}$ denotes the sigma algebra generated by the observations in all iterations before the $k$-th decision epoch.

\end{enumerate}

\label{thm:SGD_convergence_2}
Suppose that Assumption~\ref{ass:regularity} holds. Then the proposed SGD algorithm, with step size $\gamma^{\langle k\rangle}$ and sample size $n^{\langle k\rangle}$ given in \eqref{eq:step-size} and \eqref{eq:sample-size}, with $\beta > 2(1-\alpha)$,
generates a sequence of update rates $(\lambda^{\langle k\rangle})_{k=0,1,\ldots}$ that converges almost surely to the minimizer $\lambda_*$ of \eqref{eq:objective}, i.e.,

\begin{align}
\lambda^{\langle k\rangle} \xrightarrow{\text{\rm a.s.}} \lambda_*.
\label{eq:lambda_convergence}
\end{align}

{Let $B^{\langle k\rangle}$ denote the estimation bias of the gradient at iteration $k$, defined by

\begin{equation}\label{eq:bias_g}
B^{\langle k\rangle}
:=
g(\lambda^{\langle k\rangle}; \bm{\theta}_{\lambda^{\langle k\rangle}})
-
g(\lambda^{\langle k\rangle};\hat{\bm{\theta}}^{\langle k\rangle}),
\qquad k = 1,2,\ldots.
\end{equation}

Since both $\lambda^{\langle k\rangle}$ and $\hat{\bm{\theta}}^{\langle k\rangle}$ are random, $B^{\langle k\rangle}$ is a random variable.
The iteration \eqref{eq:update-lambda} can then be rewritten as

\begin{align*}
\lambda^{\langle k+1\rangle}
&=
\lambda^{\langle k\rangle}
-\gamma^{\langle k\rangle}
\left\{
g\!\left(\lambda^{\langle k\rangle};\bm{\theta}_{\lambda^{\langle k\rangle}}\right)
+\kappa'(\lambda^{\langle k\rangle})
\right\}
+\gamma^{\langle k\rangle} B^{\langle k\rangle}
+ Y^{\langle k\rangle},
\end{align*}

where the `projection residual' $Y^{\langle k\rangle}$ is defined via

\[
Y^{\langle k\rangle}
:=
\Pi_{\mathcal{L}}\!\left[\lambda^{\langle k\rangle} - \gamma^{\langle k\rangle} \hat{G}^{\langle k\rangle}\right]
-
\left(\lambda^{\langle k\rangle} - \gamma^{\langle k\rangle} \hat{G}^{\langle k\rangle}\right),
\quad
\hat{G}^{\langle k\rangle}
:=
g\!\left(\lambda^{\langle k\rangle};\hat{\bm{\theta}}^{\langle k\rangle}\right)
+\kappa'(\lambda^{\langle k\rangle}).
\]

The term $Y^{\langle k\rangle}$ is nonzero only when the unconstrained update leaves the feasible set $\mathcal{L}$, and in that case it represents the correction enforcing projection onto $\mathcal{L}$.

Let $\mathcal{F}^{\langle k-1\rangle}$ denote the sigma algebra generated by the observations in all iterations before the $k$-th decision epoch, i.e., 

\[
\mathcal{F}^{\langle k-1\rangle}:=\sigma\left((D_1^{\dag},G_1^{\dag}),(D_2^{\dag},G_2^{\dag})\ldots,(D^\dag_{\ell^{\langle k\rangle}},G^\dag_{\ell^{{\langle k\rangle}}}), \lambda^{\langle k-1\rangle}\right).
\]

Recall that $\lambda^{\langle k\rangle}$ is determined by $\lambda^{\langle k-1\rangle}$ and the data 
$((G_{\ell}^{\dag}, D_{\ell}^{\dag}))_{\ell \in \{\ell^{\langle k-1\rangle}+1,\ell^{\langle k-1\rangle}+2,\ldots,\ell^{\langle k\rangle}\}}$ observed in iteration $k-1$ (cf.\ \eqref{eq:hat-theta-def} and \eqref{eq:update-lambda}). 
Furthermore, we define $b^{\langle k\rangle}$ as the absolute mean bias:
\[
b^{\langle k\rangle} := \left| \mathbb{E}\!\left[ B^{\langle k\rangle} \, \Big|\, \lambda^{\langle k\rangle}, \mathcal{F}^{\langle k-1\rangle} \right] \right|.
\] 
Assumption~\ref{ass:regularity} (iii) ensures that 
the optimal $\lambda_*$ is the unique solution of \eqref{eq:zero_gradient}.
Therefore, owing to \cite[Page 127]{KY2003},
the almost sure convergence \eqref{eq:lambda_convergence} holds if the following conditions are satisfied:

\begin{enumerate}

\par\hangindent 40\p@[(i)] The step size sequence satisfies
\begin{align*}
\sum_{k=1}^\infty \gamma^{\langle k\rangle}=\infty, 
\quad 
\sum_{k=1}^\infty (\gamma^{\langle k\rangle})^2 < \infty.
\end{align*} 

\par\hangindent 40\p@[(ii)] There exists a constant $M<\infty$ such that for any $\lambda^{\langle k\rangle}\in[\lambda_{\min},\lambda_{\max}]$ and $n^{\langle k\rangle}$,

\begin{equation}\label{eq:variance_bound}
\mathbb{E}\!\left[\left(B^{\langle k\rangle}\right)^2 \, \Big|\,  \lambda^{\langle k\rangle}, \mathcal{F}^{\langle k-1\rangle} \right] \le M.
\end{equation}

\par\hangindent 40\p@[(iii)] The sample size sequence $(n^{\langle k\rangle})_{k=1,2,\ldots}$ satisfies, almost surely,
\begin{equation}\label{eq:bias}
\sum_{k=1}^\infty \gamma^{\langle k\rangle}|b^{\langle k\rangle}|<\infty .
\end{equation}

\end{enumerate} 

It is readily verified that $\gamma^{\langle k\rangle}$ given by \eqref{eq:step-size} satisfies (i).
Therefore, the proof requires verifying (ii) and (iii).


First of all, from Assumption~\ref{ass:regularity} (iv) and the definition
\eqref{eq:bias_g} of $B^{\langle k\rangle}$, we have

\begin{align*}
\mathbb{E}\!\left[ \left(B^{\langle k\rangle}\right)^2 \, \Big|\,
\mathcal{F}^{\langle k-1\rangle}, \lambda^{\langle k\rangle} \right]
&\le C_1^2 \,
\mathbb{E}\!\left[
\left\|
\bm{\theta}_{\lambda^{\langle k\rangle}}
-
\hat{\bm{\theta}}^{\langle k\rangle}
\right\|^2
\, \Big|\,
\mathcal{F}^{\langle k-1\rangle}, \lambda^{\langle k\rangle}
\right].
\end{align*}

Assumption~\ref{ass:regularity} (v) thus implies

\begin{align*}
\mathbb{E}\!\left[
\left(B^{\langle k\rangle}\right)^2 \, \Big|\,
\mathcal{F}^{\langle k-1\rangle},\lambda^{\langle k\rangle}
\right]
\leq
\frac{C_1^2 C_2}{n^{\langle k\rangle}}.
\end{align*}

Since $n^{\langle k\rangle}$ is an increasing sequence of positive integers, we
conclude that \eqref{eq:variance_bound} holds with
$M=C_1^2C_2$.

Furthermore, by the Cauchy--Schwarz inequality,

\begin{align*}
|b^{\langle k\rangle}|
&=
\left|
\mathbb{E}\!\left[
B^{\langle k\rangle} \, \Big|\,
\mathcal{F}^{\langle k-1\rangle}, \lambda^{\langle k\rangle}
\right]
\right|\\
&\le
\sqrt{
\mathbb{E}\!\left[
\left(B^{\langle k\rangle}\right)^2 \, \Big|\,
\mathcal{F}^{\langle k-1\rangle}, \lambda^{\langle k\rangle}
\right]
}
\leq
\frac{C_1\sqrt{C_2}}{\sqrt{n^{\langle k\rangle}}}.
\end{align*}

Therefore, we obtain \eqref{eq:bias} from \eqref{eq:step-size} and
\eqref{eq:sample-size}, as follows:

\begin{align*}
\sum_{k=1}^\infty \gamma^{\langle k\rangle}|b^{\langle k\rangle}|
&\leq
C_1\sqrt{C_2}
\sum_{k=1}^\infty
\frac{c_1 k^{-\alpha}}{\sqrt{c_2 k^{\beta}}}
=
\frac{C_1\sqrt{C_2}\,c_1}{\sqrt{c_2}}
\sum_{k=1}^\infty
\frac{1}{k^{\alpha+\beta/2}}
<\infty,
\end{align*}

recalling the condition $\beta > 2(1-\alpha)$.
}

\label{lem:theta_FD}
    Suppose that 

    $\mathbb{E}[H^4]<\infty$. Then \eqref{eq:theta_mixing} applies for any
    \begin{align}
    \label{eq:epsbound}
        \epsilon<\frac{1}{2}\min\left\lbrace\ \frac{1}{\lambda_{\max}}-\mathbb{E}[H]\,, {K-\mathbb{E}[H^2]\,,} \,f_H^*(\lambda_{\max})\right\rbrace.
    \end{align}

\label{lem:ineq}
For any non-negative random variable $Y$ with $\mathbb{E}[Y] \leq 1$, we have

\begin{align}
\mathbb{E}[Ye^{-Y}] &\leq \mathbb{E}[e^{-Y}],
\label{eq:YexpY-bound}
\\
\mathbb{E}[Y^2e^{-Y}] &\leq \mathbb{E}[e^{-Y}].
\label{eq:Y2expY-bound}
\end{align}

Under the stability condition (\ref{eq:stability}), we have

\begin{align}
\zeta(\lambda,\lambda_\mathrm{bg})+\lambda \zeta'(\lambda,\lambda_\mathrm{bg}) &\geq 0,
\label{eq:zeta-ineq-1}\\
\zeta(\lambda,\lambda_\mathrm{bg}) - \lambda^2 \zeta''(\lambda) &\geq 0.
\label{eq:zeta-ineq-2}
\end{align}

By the triangle inequality, bearing in mind $
{\boldsymbol \theta}\equiv (\mathbb{E}[H],\mathbb{E}[H^2],f_H^*(\lambda),f_H'(\lambda))$,
\begin{align}
\mathbb{E}_{\lambda^{\langle k\rangle}}\!\left[ \|\bm{\theta}_{\lambda^{\langle k\rangle}} - \hat{\bm{\theta}}^{\langle k\rangle}\|^2 \right]
\leq\,&
\mathbb{E}\!\left[\left|\hat{h}_{1,n^{\langle k\rangle}}-\mathbb{E}[H]\right|^2\right]
+\mathbb{E}\!\left[\left|\hat{h}_{2,n^{\langle k\rangle}}-\mathbb{E}[H^2]\right|^2\right] \notag \\
&
{}+
\mathbb{E}\!\left[\left|\hat{h}_{3,n^{\langle k\rangle}}(\lambda)-\mathbb{E}[e^{-\lambda H}]\right|^2\right]
+\mathbb{E}\!\left[\left|\hat{h}_{4,n^{\langle k\rangle}}(\lambda)-\mathbb{E}[-He^{-\lambda H}]\right|^2\right]. \label{eq:trian}
\end{align}
Therefore, it suffices to verify the required condition for each term on the right-hand side separately. Since the observations $(H_i)_{i\geq 1}$ are i.i.d., we have for any $n\in{\mathbb N}$,
\begin{equation}\label{eq:sigma_H}
\mathbb{E}\left[\left|\frac{1}{n}\sum_{i=1}^n \varphi(H_i)-\mathbb{E}[\varphi(H)]\right|^2\right]
=\frac{\operatorname{Var}\!\left(\varphi(H)\right)}{n},
\end{equation}
for any square-integrable function $\varphi(\cdot)$. Moreover, if $\mathbb{E}[H^4]<\infty$, then 
\begin{align}
\tilde{C}_2
:=
\sup_{\lambda\in[\lambda_{\min},\lambda_{\max}]}
\max\left\{
\operatorname{Var}(H),\,
\operatorname{Var}(H^2),\,
\operatorname{Var}(e^{-\lambda H}),\,
\operatorname{Var}(-He^{-\lambda H})
\right\}
<\infty.
\end{align}
Define the event
\begin{align*}
A_\epsilon
:={}&
\left\{
\frac{1}{n^{\langle k\rangle}}\sum_{i=1}^{n^{\langle k\rangle}} H_i
>
\frac{1}{\lambda_{\max}}-\epsilon
\right\}
\cup
\left\{
\frac{1}{n^{\langle k\rangle}}\sum_{i=1}^{n^{\langle k\rangle}} H_i^2
>
K-\epsilon
\right\} \cup
\left\{
\frac{1}{n^{\langle k\rangle}}\sum_{i=1}^{n^{\langle k\rangle}}
e^{-\lambda_{\max}H_i}
<
\epsilon
\right\},
\end{align*}
and observe that the estimator is truncated only on the event \(A_\epsilon\). By Boole's inequality,
\begin{align*}
\mathbb{E}[\mathbf{1}\{A_\epsilon\}]
&\leq 
\mathbb{P}\left(
\frac{1}{n^{\langle k\rangle}}\sum_{i=1}^{n^{\langle k\rangle}}H_i>\frac{1}{\lambda_{\max}}-\epsilon
\right)
+\mathbb{P}\left(
\frac{1}{n^{\langle k\rangle}}\sum_{i=1}^{n^{\langle k\rangle}}H_i^2>K-\epsilon
\right)\\
&\quad+
\mathbb{P}\left(
\frac{1}{n^{\langle k\rangle}}\sum_{i=1}^{n^{\langle k\rangle}}e^{-\lambda_{\max}H_i}<\epsilon
\right).
\end{align*}
We proceed by identifying upper bound on the three probabilities in the right-hand side of the previous display, thus yielding an upper bound on $\mathbb{E}[\mathbf{1}\{A_\epsilon\}]$. 
\begin{itemize}
\par\hangindent 40\p@ By \eqref{eq:epsbound} we have $2\epsilon<\lambda_{\max}^{-1}-\mathbb{E}[H]$, which is equivalent to $\mathbb{E}[H]+2\epsilon<\lambda_{\max}^{-1}$. Therefore,
\begin{align*}
\mathbb{P}\left(\frac{1}{n^{\langle k\rangle}}\sum_{i=1}^{n^{\langle k\rangle}}H_i>\frac{1}{\lambda_{\max}}-\epsilon\right)\leq 
\mathbb{P}\left(\left| \frac{1}{n^{\langle k\rangle}}\sum_{i=1}^{n^{\langle k\rangle}}H_i-\mathbb{E}[H]\right|> \epsilon\right).
\end{align*}
Applying Chebyshev's inequality and \eqref{eq:sigma_H} yields
\begin{align*}
\mathbb{P}\left(\frac{1}{n^{\langle k\rangle}}\sum_{i=1}^{n^{\langle k\rangle}}H_i>\frac{1}{\lambda_{\max}}-\epsilon\right)\leq \frac{\operatorname{Var}(H)}{\epsilon^2 n^{\langle k\rangle}}\leq \frac{\tilde{C}_2}{\epsilon^2 n^{\langle k\rangle}}.
\end{align*}
\par\hangindent 40\p@ Similarly, \eqref{eq:epsbound} yields $\mathbb{E}[H^2]<K-2\epsilon$, so that
\begin{align*}
\mathbb{P}\left(\frac{1}{n^{\langle k\rangle}}\sum_{i=1}^{n^{\langle k\rangle}}H_i^2>K-\epsilon\right)\leq \frac{\operatorname{Var}[H^2]}{\epsilon^2 n^{\langle k\rangle}}\leq \frac{\tilde{C}_2}{\epsilon^2 n^{\langle k\rangle}},
\end{align*}
\par\hangindent 40\p@ Finally, $\epsilon<{f_H^*(\lambda_{\max})}/{2}$ implies $\epsilon<f_H^*(\lambda_{\max})-\epsilon$, and
\begin{align*}
\mathbb{P}\left(\frac{1}{n^{\langle k\rangle}}\sum_{i=1}^{n^{\langle k\rangle}}e^{-\lambda_{\max} H_i}<\epsilon\right)&\leq \mathbb{P}\left(\left|\frac{1}{n^{\langle k\rangle}}\sum_{i=1}^{n^{\langle k\rangle}}e^{-\lambda_{\max} H_i}-f_H^*(\lambda_{\max})\right|>\epsilon\right)\\&\leq \frac{\operatorname{Var}[e^{-\lambda_{\max} H}]}{\epsilon^2 n^{\langle k\rangle}}\leq \frac{\tilde{C}_2}{\epsilon^2 n^{\langle k\rangle}}.
\end{align*}
\end{itemize}

Observe that for $j=1,2$,
with ${\mathscr C}_j$ being an upper bound on both $\hat{h}_{j,n^{\langle k\rangle}}^2$ and $\theta_j^2$, the standard inequality $(x-y)^2\le 2(x^2+y^2)$ yields

\begin{align}
\mathbb{E}\left[|\hat{h}_{j,n^{\langle k\rangle}}-\theta_j|^2\right]&=\mathbb{E}[|\hat{h}_{j,n^{\langle k\rangle}}-\theta_j|^2\mathbf{1}\{A_\epsilon\}]+\mathbb{E}[|\hat{h}_{j,n^{\langle k\rangle}}-\theta_j|^2\mathbf{1}\{{A}^{\rm c}_\epsilon\}] \notag\\
&\leq 4\,{\mathscr C}_j\,\mathbb{E}[\mathbf{1}\{A_\epsilon\}]+\mathbb{E}\left[\left|\frac{1}{n^{\langle k\rangle}}\sum_{i=1}^{n^{\langle k\rangle}}H_i^j-\mathbb{E}[H^j]\right|^2\right].\label{eq:BND}
\end{align}

We now identify an upper bound on the first term in the right hand side of \eqref{eq:trian}. 
By \eqref{eq:sigma_H},
\[\mathbb{E}\left[\left|\frac{1}{n^{\langle k\rangle}}\sum_{i=1}^{n^{\langle k\rangle}}H_i-\mathbb{E}[H]\right|^2\right]\le \frac{\operatorname{Var}(H)}{n^{\langle k\rangle}}\le\frac{\tilde {C}_2}{n^{\langle k\rangle}}.\]
Because $\smash{\hat{h}_{1,n^{\langle k\rangle}}\le \lambda_{\max}^{-1} -\epsilon \le \lambda_{\max}^{-1}}$ and $\theta_1=\smash{\mathbb{E}[H]\le \lambda_{\max}^{-1} -2\epsilon \le \lambda_{\max}^{-1}}$, we obtain from \eqref{eq:BND} that
\begin{align*}
\mathbb{E}\left[|\hat{h}_{1,n^{\langle k\rangle}}-\mathbb{E}[H]|^2\right]
&\leq {\frac{4}{\lambda^2_{\max}}}\mathbb{E}[\mathbf{1}\{A_\epsilon\}]+\mathbb{E}\left[\left|\frac{1}{n^{\langle k\rangle}}\sum_{i=1}^nH_i-\mathbb{E}[H]\right|^2\right],
\end{align*}
so that
\[\mathbb{E}\left[|\hat{h}_{1,n^{\langle k\rangle}}-\mathbb{E}[H]|^2\right]\le \frac{\tilde{C}_2}{n^{\langle k\rangle}}\left(1+\frac{6}{\lambda_{\max}^2\epsilon^2}\right).\]
We proceed by analyzing the second term in the right hand side of \eqref{eq:trian}. Following the exact same procedure, noting that both $\smash{\hat{h}_{2,n^{\langle k\rangle}}}$ and $\theta_2=\mathbb{E}[H^2]$ are majorized by $K$, again by \eqref{eq:BND},
\[ \mathbb{E}\left[|\hat{h}_{2,n^{\langle k\rangle}}-\mathbb{E}[H^2]|^2\right]\le \frac{\tilde{C}_2}{n^{\langle k\rangle}}\left(1+\frac{6K^2}{\epsilon^2}\right).\]

Then we consider the third term in the right-hand side of \eqref{eq:trian}. Now note that both $\smash{\hat{h}_{3,n^{\langle k\rangle}}(\lambda)}$ and $\mathbb{E}[e^{-\lambda H}]$ are bounded above by 1. Hence,
\begin{align*}

\mathbb{E}\left[|\hat{h}_{3,n^{\langle k\rangle}}(\lambda)-\mathbb{E}[e^{-\lambda H}]|^2\right]&\leq  \frac{\tilde{C}_2}{n^{\langle k\rangle}}\left(1+\frac{6}{\epsilon^2}\right).
\end{align*}
For the remaining term, directly from \eqref{eq:sigma_H}, we obtain
\begin{align*}
\mathbb{E}\left[|\hat{h}_{4,n^{\langle k\rangle}}(\lambda)-\mathbb{E}[-He^{-\lambda H}]|^2\right]&\leq \frac{\tilde{C}_2}{n^{\langle k\rangle}}.
\end{align*}
We conclude that with 
\begin{align*}
C_2:={\tilde{C}_2}\left(4+\frac{6}{\epsilon^2}\left(\lambda_{\max}^{-2}+K^2+1\right)\right)
\end{align*}
the stated assertion \eqref{eq:theta_mixing} holds.

\label{lem:D_mixing}
    Suppose $\mathbb{E}[H^2]<\infty$ and that $D_0=d_0\leq w$. 
    \begin{itemize}

    \par\hangindent 40\p@[(i)] For any measurable function $f:[0,\infty)\times\mathcal{L}\to[0,1]$ there exists a positive constant $K_1<\infty$ such that, for all $n\in{\mathbb N}$,
    \begin{equation}   \label{eq:D_mixing}     
    \sup_{\lambda\in\mathcal{L}}\sup_{d_0\leq w}
    \mathbb{E}_{\lambda}\left[
    \left|\frac{1}{n}\sum_{i=1}^n
    \left(f(D_i,\lambda)-\mathbb{E}_\lambda[f(D,\lambda)]\right)\right|^2
    \, \Big|\,  D_0=d_0
    \right]
    \leq \frac{K_1}{n} .
    \end{equation}

    \par\hangindent 40\p@[(ii)] Consider the parameterized class of functions $\mathcal{F}=\{f_\ell:[0,\infty)\times\mathcal{L}\to[0,1]\ : \ell\in[\ell_1,\ell_2]\}$. If for every $d\geq0$, $f_\ell(d,\lambda)$ is absolutely continuous (with respect to $\ell)$ and 
    \begin{align*} 
    \bar{m}:= \sup_{\ell\in[\ell_1,\ell_2],\ d\geq 0,\ \lambda\in\mathcal{L}}|\frac{\mathrm{d} }{\mathrm{d} \ell}f_\ell(d,\lambda)|<\infty , 
    \end{align*}
    then there exists a constant $K_2$ such that

    \begin{equation}   \label{eq:D_mixing_2}     
    \sup_{\lambda\in\mathcal{L}}\sup_{d_0\leq w}
    \mathbb{E}_\lambda\left[
    \sup_{\ell\in[\ell_1,\ell_2]}
    \left|
    \frac{1}{n}\sum_{i=1}^n
    \left(f_\ell(D_i,\lambda)-\mathbb{E}_\lambda[f_\ell(D,\lambda)]\right)
    \right|^2
    \, \Big|\,  D_0=d_0
    \right]
    \leq \frac{K_2}{n}. 
    \end{equation}

    \end{itemize}
